{
  "name": "opencode-diff-viewer",
  "version": "1.0.11",
  "description": "OpenCode plugin + CLI tool for launching AI agents in tmux with diff viewing",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "bin": {
    "diffviewer": "./bin/diffviewer"
  },
  "files": [
    "dist/",
    "command-diff.md",
    "bin/",
    "start-opencode.sh"
  ],
  "scripts": {
    "build": "tsc",
    "start": "./start-opencode.sh",
    "diffviewer": "./bin/diffviewer"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "diff",
    "lumen",
    "tmux",
    "cli",
    "agent-launcher",
    "git"
  ],
  "author": "AarynLu",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/AruNi-01/opencode-diff-viewer"
  },
  "bugs": {
    "url": "https://github.com/AruNi-01/opencode-diff-viewer/issues"
  },
  "homepage": "https://github.com/AruNi-01/opencode-diff-viewer#readme",
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.0.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.0.0",
    "@types/node": "^25.0.3",
    "typescript": "^5.0.0"
  }
}
